INSERT INTO public.book_compasses (slug, name, description, quote, quote_attribution, timing, tools, practices, phase_affinity, order_index, status) VALUES
('ux-consciousness','The UX Consciousness','Guiding principle for user-centric design.','The goal of life is living in agreement with nature.','Zeno of Citium','Throughout design process',ARRAY['User-centered design frameworks','empathy mapping','VR/AR'],ARRAY['Design thinking','User interviews','Usability testing'],ARRAY['LOVE','CALM'],1,'draft'),
('body-maps','Body Maps','Personalized learning through bodily awareness.','In every walk with nature, one receives far more than he seeks.','John Muir','Tailored to individual needs',ARRAY['Wearable tech','Biometric sensors','3D modeling'],ARRAY['Yoga','Meditation','Kinesthetic learning'],ARRAY['LOVE','CALM'],2,'draft'),
('iot-iob','Internet of Things & Internet of Bodies','Enhanced learning in a connected world.','We have paleolithic emotions, medieval institutions, and godlike technology.','E.O. Wilson','Leveraging connectivity',ARRAY['Smart sensors','Health trackers','Remote labs'],ARRAY['Hands-on experiments','Field trips','Remote collaborations'],ARRAY['DRIFT','OPEN'],3,'draft'),
('cognitive-maps','Cognitive Maps','Understanding and optimizing learning processes.','The only real valuable thing is intuition.','Albert Einstein','Continuous monitoring',ARRAY['Data analytics','Neural networks','Brain-computer interfaces'],ARRAY['Mind mapping','Reflective journaling','Metacognition'],ARRAY['DRIFT','MAGIC'],4,'draft'),
('ubiquitous-computing','Ubiquitous Computing','Integration of technology in daily life.','You are not a drop in the ocean. You are the entire ocean in a drop.','Rumi','In an increasingly digital world',ARRAY['Cloud computing','Edge computing','Ambient intelligence'],ARRAY['Digital detox','Mindfulness','Screen-free time'],ARRAY['CALM','OPEN'],5,'draft'),
('prediction-engines','Prediction Engines','Proactive adaptation to individual learning needs.','The future belongs to those who believe in the beauty of their dreams.','Eleanor Roosevelt','Ongoing data analysis',ARRAY['Machine learning','Recommender systems'],ARRAY['Goal setting','Adaptive learning','Feedback loops'],ARRAY['DRIFT','FREE'],6,'draft'),
('worldbuilding-narratives','Worldbuilding Narratives','Shaping the learning environment through dominant and emergent stories.','The only limits to the possibilities in your life tomorrow are the buts you use today.','Les Brown','Throughout curriculum design',ARRAY['Storytelling platforms','Virtual worlds','Scenario planning'],ARRAY['Storytelling workshops','Role-playing','Scenario analysis'],ARRAY['MAGIC','DRIFT'],7,'draft'),
('usability','Usability','Enhancing human-computer interaction.','The only way to do great work is to love what you do.','Steve Jobs','In product design',ARRAY['Usability testing','NLP','Gesture recognition'],ARRAY['Heuristic evaluation','Usability guidelines'],ARRAY['CALM','TUNE'],8,'draft'),
('post-broadcast-engagement','Engaging Learners in a Post-Broadcast World','Interactive content for participatory media.','We are now in the non-broadcast era.','Douglas Coupland','In media design',ARRAY['Interactive content tools','Personalized media','Audience participation'],ARRAY['Participatory authoring','Co-creation'],ARRAY['OPEN','TUNE'],9,'draft'),
('future-envisioning','Filling Gaps in Envisioning the Future','Closing the future-narratives deficit.','The future depends on what we do in the present.','Mahatma Gandhi','In strategy & foresight',ARRAY['Scenario planning','Speculative fiction','Foresight exercises'],ARRAY['Trendspotting','Trend analysis','Visioning'],ARRAY['MAGIC','DRIFT'],10,'draft'),
('dialogic-imagination','Dialogic Imagination','Critical thinking through dialogue.','Dialogue is the most effective way of resolving conflict.','Dalai Lama','In group discussions',ARRAY['Debate platforms','Collaborative tools'],ARRAY['Socratic questioning','Perspective-taking'],ARRAY['TUNE','OPEN'],11,'draft'),
('futurogram','Futurogram','Transitioning to the Sensor Age.','The future is already here — it is just not evenly distributed.','William Gibson','In technological transitions',ARRAY['Sensor networks','Data visualization','Predictive analytics'],ARRAY['Tech impact assessment','Ethical tech adoption'],ARRAY['DRIFT','OPEN'],12,'draft'),
('purpose-meaning-work','Purpose & Meaning at Work','Enhancing fulfillment in professional settings.','Your work is going to fill a large part of your life — the only way to be truly satisfied is to do what you believe is great work.','Steve Jobs','In career development',ARRAY['Engagement surveys','Coaching platforms'],ARRAY['Career counseling','Values exploration','Job crafting'],ARRAY['LOVE','TUNE'],13,'draft'),
('noetic-functions','The Noetic Functions','Exploring the cognitive aspects of learning.','The mind is not a vessel to be filled, but a fire to be kindled.','Plutarch','During cognitive development',ARRAY['Cognitive research','Mind mapping'],ARRAY['Metacognitive strategies','Critical thinking'],ARRAY['MAGIC','DRIFT'],14,'draft'),
('human-animal','The Human Animal','Understanding human behavior and evolution.','The greatest mystery of existence is existence itself.','Deepak Chopra','Throughout the journey',ARRAY['Anthropology','Behavioral economics','Simulations'],ARRAY['Ethnographic research','Behavioral experiments'],ARRAY['LOVE','GLITCH'],15,'draft'),
('ecological-truth','Ecological Truth & Eco-Anxiety','Addressing environmental concerns.','We will not have a society if we destroy the environment.','Margaret Mead','In ecological education',ARRAY['Sustainability ed','Eco-awareness campaigns'],ARRAY['Eco-friendly practice','Conservation initiatives'],ARRAY['CALM','FREE'],16,'draft'),
('reinventing-education','Reinventing Education','Innovating education for future needs.','Education is the most powerful weapon which you can use to change the world.','Nelson Mandela','In educational reform',ARRAY['EdTech','Experiential learning'],ARRAY['Curriculum redesign','Project-based learning','Peer mentoring'],ARRAY['OPEN','FREE'],17,'draft'),
('the-calmness','The Calmness','Promoting mindfulness and well-being.','The present moment is the only moment available to us, and it is the door to all moments.','Thich Nhat Hanh','During stress management',ARRAY['Meditation apps','Wellness programs'],ARRAY['Mindfulness meditation','Deep breathing'],ARRAY['CALM','TUNE'],18,'draft'),
('meaningfulness','Seeking Meaningfulness','Existential clarity and self-discovery.','To live is the rarest thing in the world. Most people exist, that is all.','Oscar Wilde','In life-design work',ARRAY['Existential philosophy','Self-discovery journeys'],ARRAY['Journaling','Life-purpose workshops'],ARRAY['LOVE','TUNE'],19,'draft'),
('playfulness','Encouraging Playfulness','Creativity through play.','We do not stop playing because we grow old; we grow old because we stop playing.','George Bernard Shaw','In ideation',ARRAY['Gamification','Playful learning','Artistic expression'],ARRAY['Creative ideation','Game-based learning'],ARRAY['MAGIC','GLITCH'],20,'draft'),
('attention-calm','Emphasizing Calm Attention','Mindful technology use.','Calm mind brings inner strength and self-confidence.','Dalai Lama','In tech-life balance',ARRAY['Mindful tech','Serene interfaces','Digital boundaries'],ARRAY['Digital detox','Tech curfews'],ARRAY['CALM','FREE'],21,'draft'),
('usefulness','Usefulness','Ensuring practicality and value.','The only way to do great work is to love what you do.','Steve Jobs','During project planning',ARRAY['Utility assessments','User feedback','Task-oriented design'],ARRAY['Lean methods','Value proposition canvases'],ARRAY['CALM','OPEN'],22,'draft'),
('serendipity','Serendipity','Embracing unexpected discoveries.','Look for something, find something else, and realize that what you have found is more suited to your needs than what you thought you were looking for.','Lawrence Block','Throughout the process',ARRAY['Open exploration','Wide reading','Cross-domain travel'],ARRAY['Wandering','Improvisation','Beginner mind'],ARRAY['MAGIC','FREE'],23,'draft');
INSERT INTO public.book_reflection_nodes (chapter_slug, kind, title, body_md, source_ref, language, status, order_index) VALUES
('naming-the-friction','bilingual_passage','Je réfléchis à réfléchir','J''ai passé la plus grande partie de ma vie à chercher des explications sur tout ce que je ressentais de l''univers qui m''entourait. Sur tout. Avidement.','Préface, Official Book Structure','fr','draft',1),
('naming-the-friction','conversation_starter','The unfiltered question','Everyone has a built-in censoring system that filters thoughts and stimuli before they reach conscious awareness. What did your filter quietly remove from this week?','CALM MAGIC intro, p.1','en','draft',2),
('naming-the-friction','fragment','Mes questionnements actuels','Quelles questions, posées aujourd''hui, transformeraient votre rapport au travail dans 12 mois ?','Part 1 — The Compasses','fr','draft',3),
('pattern-exploration','fragment','Futurogram','From the Web to the Industrial Internet of Things, to a programmable world: how do we imagine the impact of spatial computing on a body, a team, a city?','Part 1, Futurogram','en','draft',1),
('pattern-exploration','reflection','Programmable World','When the world becomes programmable, design stops being decoration and starts being legislation. Whose laws are you writing today?','Part 1','en','draft',2),
('pattern-exploration','conversation_starter','Worldbuilding check','Name one dominant narrative shaping your team and one emergent narrative trying to break through.','Wild Cookie — Worldbuilding Narratives','en','draft',3),
('intentional-commitment','reflection','Reinventing Meetings','Treat each meeting as an encounter, not a transaction. Inspire → Play → Model → Execute, with phases of divergence, exploration, convergence.','Part 3 — Reinventing Meetings','en','draft',1),
('intentional-commitment','conversation_starter','StoryTime ritual','What ritual of listening, recitation, or co-narration could you install before the next decision is made?','L''importance du StoryTime','en','draft',2),
('intentional-commitment','fragment','Tune the encounter','Usage gives meaning. Create new experiences using tools and methods to communicate the new — new ways of seeing, thinking, learning, doing.','Why Organizational Poetry Works','en','draft',3),
('relational-infrastructure','bilingual_passage','Le qui avant le quoi','Je suis davantage dans le social good : la cause plus que le résultat. Je cherche les talents avant le client : le qui en premier, ensuite le quoi.','Part 3','fr','draft',1),
('relational-infrastructure','reflection','Engagement, not extraction','Self-Determination Theory: people are engaged at the intersection of autonomy, mastery, and purpose. Disengagement is a design failure, not a personality flaw.','Page 11 — Engaging people at work','en','draft',2),
('relational-infrastructure','conversation_starter','Purpose at work','Where in your week does work feel like poiesis — bringing into being something that did not exist before — and where does it feel like maintenance?','Wild Cookie — Purpose & Meaning','en','draft',3),
('pragmatic-imagination','fragment','Poiesis at the Office','Poiesis (ποίησις): the activity in which a person brings something into being that did not exist before. An office can be a workshop of poiesis or a warehouse of repetition.','Part 1 — Poiesis at the Office','en','draft',1),
('pragmatic-imagination','conversation_starter','Pull a serendipity card','What were you looking for this month, and what did you actually find that turned out to matter more?','Wild Cookie — Serendipity','en','draft',2),
('pragmatic-imagination','reflection','Playgrounds before plans','Lower the stakes for trying. Before committing to a plan, design three small, safe experiments that would teach you the most.','Playground Compass','en','draft',3),
('pragmatic-imagination','fragment','Dialogic imagination','The most generative ideas usually arrive in the second half of a real conversation. Stay long enough.','Wild Cookie — Dialogic Imagination','en','draft',4),
('designing-the-system','reflection','The Calmness','Calm is not the absence of activity. It is a designed pace that protects attention as the scarcest resource in the system.','Wild Cookie — The Calmness','en','draft',1),
('designing-the-system','conversation_starter','Attention budget','If your team had a fixed monthly budget of attention units, where are you currently overspending?','Wild Cookie — Calm Attention','en','draft',2),
('designing-the-system','fragment','Calm Computing','Serene interfaces, technology curfews, digital boundaries. The system you design teaches the nervous system it touches.','Wild Cookie — Ubiquitous + Calm','en','draft',3),
('living-the-ontology','reflection','Organizational Poetics','Organizational design is poetry. Structures, rituals, and language are stanzas — they shape what can and cannot be said, decided, or felt inside a company.','Part 3 — The Organizational Poet','en','draft',1),
('living-the-ontology','conversation_starter','Story-driven transformation','Which story is your enterprise telling itself, and which story is the market actually hearing?','Story-Driven Enterprise Transformation','en','draft',2),
('living-the-ontology','fragment','The learning organization','A learning organization moves between systemic thinking, poiesis ↔ praxis, and innovation. Where is your organization stuck on that loop?','Page 22','en','draft',3),
('living-the-ontology','bilingual_passage','L''entreprise est un réseau','Comment les histoires se transportent et se transforment dans un réseau ? Réinventer les meetings, les présentations et installer des rituels d''écoute, de récitation et de création de récits.','Story-Driven Enterprise Transformation','fr','draft',4),
('operating-in-flow','reflection','Creative/Transition Design Expeditions','For any enterprise wishing to transition toward a learning-organization model: organize the work as an expedition, not a project. Expeditions assume terrain you have not mapped.','Part 3','en','draft',1),
('operating-in-flow','conversation_starter','Activity map','Draw the activity map of one person on your team this week. What is over-represented? What is missing entirely?','Activity Maps','en','draft',2),
('operating-in-flow','fragment','Ecological truth','Operating in flow without ecological truth is just acceleration. Where is your speed colliding with the planet, the body, or the relationship?','Wild Cookie — Ecological Truth','en','draft',3),
('operating-in-flow','reflection','Reinventing education at work','Every team is an informal school. What is yours actively teaching its members about how to think, decide, and care?','Wild Cookie — Reinventing Education','en','draft',4);
